def page(key,title,desc,body,bare=False):
    R="" if key=="index" else "../"
    L=lambda k:(R+"index.html") if k=="index" else (("pages/" if R=="" else "")+k+".html")
    def item(n,t,m=False):
        if isinstance(t,str): return f'<li><a href="{L(t)}" class="{"on" if t==key else ""}">{n}</a></li>'
        return f'<li><a href="#" onclick="return false">{n} <i class="fa-solid fa-chevron-down" style="font-size:.6rem"></i></a><div class="dd'+(' mega' if m else '')+'">'+"".join(f'<a href="{L(k)}">{m}</a>' for k,m in t)+'</div></li>'
    menu="".join(item(*e) for e in NAV)
    tick="".join(f'<span><i class="fa-solid fa-trophy"></i>{p}</span>' for p in PLACE*2)
    shell=f'''<div class="topbar"><div class="wrap"><div><span><i class="fa-solid fa-location-dot"></i>Durgapur, Paschim Bardhaman, West Bengal</span><span><i class="fa-solid fa-envelope"></i>bcrp@bcrec.ac.in</span><span><i class="fa-solid fa-phone"></i>+91 75860 23555</span></div><div><a href="{L("notices")}"><i class="fa-solid fa-bell"></i>Admission Enquiry 2026</a></div></div></div>
<header class="nav"><div class="wrap"><a class="brand" href="{L("index")}">{LOGO.replace('class="','class="x ')}<span><b>DR. B.C. ROY POLYTECHNIC</b><small>A UNIT OF DR. B.C. ROY ENGINEERING COLLEGE, DURGAPUR</small></span></a>
<button class="burger" aria-label="Menu"><i class="fa-solid fa-bars"></i></button><ul class="menu">{menu}<li><a class="login" href="{L("login")}"><i class="fa-solid fa-lock"></i>Login</a></li></ul></div></header>
<div class="ticker"><b>Highlights</b><div>{tick}</div></div>''' if not bare else ""
    foot=f'''<footer><div class="wrap"><div class="grid"><div><img class="fl" src="{R}images/logo-circle.png" alt="BCRP"><h4>DR. B.C. ROY POLYTECHNIC</h4><p>A unit of Dr. B.C. Roy Engineering College, Durgapur.<br>Affiliated to WBSCT&amp;VE&amp;SD | Approved by AICTE.</p></div>
<div><h4>Explore</h4><a href="{L("about")}">About</a><a href="{L("academics")}">Academics</a><a href="{L("admission")}">Admission</a><a href="{L("placements")}">Placement</a></div><div><h4>Campus</h4><a href="{L("student-life")}">Student Life</a><a href="{L("gallery")}">Gallery</a><a href="{L("notices")}">Notices</a><a href="{L("results")}">Results</a></div>
<div><h4>Contact</h4><p><i class="fa-solid fa-phone"></i>75860 23555 | 74777 88551</p><p><i class="fa-solid fa-envelope"></i>bcrp@bcrec.ac.in</p><p><i class="fa-solid fa-location-dot"></i>Durgapur, West Bengal</p></div></div><div class="copy">&copy; Dr. B.C. Roy Polytechnic. All rights reserved.</div></div></footer>''' if not bare else ""
    return f'''<!DOCTYPE html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>{title} | Dr. B.C. Roy Polytechnic, Durgapur</title><meta name="description" content="{desc}">
<meta property="og:title" content="{title} | Dr. B.C. Roy Polytechnic"><link rel="icon" href="{R}images/logo-circle.png"><link rel="preconnect" href="https://fonts.googleapis.com">
<link href="https://fonts.googleapis.com/css2?family=Outfit:wght@500;600;700;800&family=Plus+Jakarta+Sans:wght@400;500;600;700&display=swap" rel="stylesheet">
<link rel="stylesheet" href="https://cdnjs.cloudflare.com/ajax/libs/font-awesome/6.5.2/css/all.min.css"><link rel="stylesheet" href="{R}css/style.css"></head><body>
<div id="prog"></div>
<!-- Animated logo loader + curtain page transition (magenta, gold, plum panels) -->
<div id="loader"><div class="pn"></div><div class="pn b"></div><div class="pn c"></div><div class="lc">{LOGO}<div class="lt">DR. B.C. ROY POLYTECHNIC</div><div class="ln"><i></i></div></div></div>
{shell}<main>{body}</main>{foot}<script src="{R}js/main.js"></script></body></html>'''
def phero(t,s,k=""): return f'<section class="phero"><img src="../images/logo-circle.png" alt=""><div class="wrap"><div class="crumb">Home / {t}</div><h1 class="rv">{t}</h1><p class="rv">{s}</p></div></section>'
def head(e,t,s="",a=""): return f'<div class="head rv"><div class="eyebrow">{e}</div><h2>{t}</h2>'+(f'<p class="lead">{s}</p>' if s else "")+'</div>'
def cards(items,c="g3"): return f'<div class="grid {c}">'+"".join(f'<div class="card rv"><div class="ic"><i class="fa-solid fa-{i}"></i></div><h3>{t}</h3><p>{p}</p></div>' for i,t,p in items)+'</div>'
def sec(e,t,inner,s="",alt=False): return f'<section class="{"alt" if alt else ""}"><div class="wrap">{head(e,t,s)}{inner}</div></section>'
def dept_cards(): return cards([(i,n,(f"Diploma programme · 3 years · {s} seats" if s else "Humanities & basic science foundation for all branches")) for i,n,s in DEPTS])
