def inner(sec,slug,title,body):
    side="".join(f'<a href="{s}.html" class="{"on" if s==slug else ""}">{t}</a>' for s,t in SECS[sec])
    return phero(title,sec+" · Dr. B.C. Roy Polytechnic")+f'<section><div class="wrap cp"><aside class="side rv zl"><h4>{sec}</h4>{side}</aside><article class="box art rv zr"><h2>{title}</h2>{body or TODO%slug}</article></div></section>'
SKIP={"departments","faculty","admission","contact","placements","about"}
for sec,items in SECS.items():
    for slug,title in items:
        if slug in SKIP: continue
        P[slug]=(title,title+" | Dr. B.C. Roy Polytechnic, Durgapur",inner(sec,slug,title,C.get(slug,"")))
P["placement-status"]=("Placement Status","Placement status",inner("Placement","placement-status","Placement Status",'<div class="grid g2">'+"".join(f'<div class="card"><div class="ic"><i class="fa-solid fa-trophy"></i></div><h3>{p}</h3></div>' for p in PLACE)+'</div>'))
for slug,title in [("scholarship","Scholarship"),("achievements","Achievements")]:
    P[slug]=(title,title,phero(title,"Dr. B.C. Roy Polytechnic")+f'<section><div class="wrap" style="max-width:900px"><div class="box art">{C.get(slug) or TODO%slug}</div></div></section>')
for k,(t,d,b,*x) in [(k,v if len(v)==4 else v+(False,)) for k,v in P.items()]:
    path = BASE_DIR / ("index.html" if k == "index" else f"pages/{k}.html")
    with open(path, "w", encoding="utf-8", newline="") as f:
        f.write(page(k, t, d, b, bool(x[0]) if x else False))
print("built",len(P))
